1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #14161c;
17	    color: #e8e8ec;
18	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board {
22	    display: grid;
23	    grid-template-columns: repeat(10, 28px);
24	    grid-template-rows: repeat(20, 28px);
25	    gap: 1px;
26	    padding: 1px;
27	    background: #2a2d36;
28	    border: 2px solid #3a3e4a;
29	  }
30	  .cell { width: 28px; height: 28px; background: #0d0e12; }
31	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
32	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
33	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
34	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
35	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
36	  .next-item[data-piece] { background: transparent !important; }
37	  .preview {
38	    display: grid;
39	    grid-template-columns: repeat(4, 16px);
40	    grid-template-rows: repeat(2, 16px);
41	    gap: 1px;
42	  }
43	  .preview .mini { width: 16px; height: 16px; background: transparent; }
44	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
45	  button {
46	    font: inherit;
47	    background: #2f333d;
48	    color: #e8e8ec;
49	    border: 1px solid #454a57;
50	    padding: 6px 10px;
51	    cursor: pointer;
52	  }
53	  button:hover { background: #3a3e4a; }
54	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
55	
56	  /* Piece colours, shared by the board and the preview. */
57	  [data-piece="I"] { background: #22c5e6 !important; }
58	  [data-piece="O"] { background: #f2d024 !important; }
59	  [data-piece="T"] { background: #a64ee6 !important; }
60	  [data-piece="S"] { background: #3fcf5a !important; }
61	  [data-piece="Z"] { background: #e8423f !important; }
62	  [data-piece="J"] { background: #3563e9 !important; }
63	  [data-piece="L"] { background: #f08a24 !important; }
64	</style>
65	</head>
66	<body>
67	<div class="game">
68	  <div class="board" data-testid="board" id="board"></div>
69	  <div class="side">
70	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
71	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
72	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
73	    <div class="panel"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
74	    <div class="status" data-testid="game-over" id="status" hidden>Game over</div>
75	    <button type="button" id="restart">New game</button>
76	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop</div>
77	  </div>
78	</div>
79	<script>
80	(function () {
81	  "use strict";
82	
83	  var ROWS = 20;
84	  var COLS = 10;
85	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
86	  var MIN_UPCOMING = 5;
87	  // [REQ-006] Show only the next piece.
88	  var PREVIEW_COUNT = 1;
89	
90	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
91	  var SHAPES = {
92	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
93	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
94	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
95	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
96	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
97	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
98	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
99	  };
100	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
101	  // Size of the square box each piece rotates inside.
102	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
103	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
104	  var KICKS = [0, -1, 1, -2, 2];
105	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
106	  var LOCK_TICKS = 2;
107	  var MAX_LOCK_RESETS = 3;
108	  // Scoring (decision): points by rows cleared at once, times level. Clearing rows together
109	  // must always beat clearing the same rows in smaller groups. Soft drop 1/cell, hard drop 2/cell.
110	  var LINE_SCORES = [0, 100, 300, 500, 800];
111	  var SOFT_DROP_POINTS = 1;
112	  var HARD_DROP_POINTS = 2;
113	
114	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
115	  var board;
116	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
117	  var upcoming;  // array of piece letters, soonest first
118	  var score, level, lines, status;
119	  var timer = null;
120	
121	  var boardEl = document.getElementById("board");
122	  var previewEl = document.getElementById("preview");
123	  var scoreEl = document.getElementById("score");
124	  var levelEl = document.getElementById("level");
125	  var linesEl = document.getElementById("lines");
126	  var statusEl = document.getElementById("status");
127	  var cellEls = [];
128	  var previewItems = [];  // { el, minis } per upcoming piece shown, soonest first
129	
130	  // [REQ-001] Build the 200 board cells and the preview cells once.
131	  // [REQ-004] The preview holds PREVIEW_COUNT items, each a 4x2 grid of mini cells.
132	  // [REQ-006] PREVIEW_COUNT is 1: one item, the next piece.
133	  function buildDom() {
134	    for (var r = 0; r < ROWS; r++) {
135	      cellEls.push([]);
136	      for (var c = 0; c < COLS; c++) {
137	        var el = document.createElement("div");
138	        el.className = "cell";
139	        el.setAttribute("data-testid", "cell");
140	        el.setAttribute("data-row", String(r));
141	        el.setAttribute("data-col", String(c));
142	        el.setAttribute("data-filled", "false");
143	        el.setAttribute("data-piece", "");
144	        boardEl.appendChild(el);
145	        cellEls[r].push(el);
146	      }
147	    }
148	    for (var i = 0; i < PREVIEW_COUNT; i++) {
149	      var item = document.createElement("div");
150	      item.className = "preview next-item";
151	      item.setAttribute("data-testid", "next-piece-item");
152	      item.setAttribute("data-piece", "");
153	      var minis = [];
154	      for (var k = 0; k < 8; k++) {
155	        var m = document.createElement("div");
156	        m.className = "mini";
157	        m.setAttribute("data-piece", "");
158	        item.appendChild(m);
159	        minis.push(m);
160	      }
161	      previewEl.appendChild(item);
162	      previewItems.push({ el: item, minis: minis });
163	    }
164	  }
165	
166	  function emptyBoard() {
167	    var b = [];
168	    for (var r = 0; r < ROWS; r++) {
169	      var row = [];
170	      for (var c = 0; c < COLS; c++) row.push(null);
171	      b.push(row);
172	    }
173	    return b;
174	  }
175	
176	  function isType(t) { return TYPES.indexOf(t) !== -1; }
177	
178	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
179	  function randomBag() {
180	    var bag = TYPES.slice();
181	    for (var i = bag.length - 1; i > 0; i--) {
182	      var j = Math.floor(Math.random() * (i + 1));
183	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
184	    }
185	    return bag;
186	  }
187	
188	  function fillUpcoming() {
189	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
190	  }
191	
192	  function cellsOf(piece, row, col) {
193	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
194	  }
195	
196	  function fits(piece, row, col) {
197	    var cells = cellsOf(piece, row, col);
198	    for (var i = 0; i < cells.length; i++) {
199	      var r = cells[i][0], c = cells[i][1];
200	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
201	      if (board[r][c]) return false;
202	    }
203	    return true;
204	  }
205	
206	  // [REQ-001] Take the next piece from the queue and place it at the top.
207	  // [REQ-004] If the new piece does not fit where it spawns, the game is over.
208	  function spawn() {
209	    fillUpcoming();
210	    var type = upcoming.shift();
211	    fillUpcoming();
212	    var piece = {
213	      type: type,
214	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
215	      row: 0,
216	      col: SPAWN_COL[type],
217	      lockTicks: 0,
218	      lockResets: 0
219	    };
220	    if (!fits(piece, piece.row, piece.col)) {
221	      current = null;
222	      status = "gameover";
223	      stopTimer();
224	      return;
225	    }
226	    current = piece;
227	  }
228	
229	  // [REQ-003] Remove full rows, drop the rows above, add rows to lines and score at the current level.
230	  function clearLines() {
231	    var kept = board.filter(function (row) {
232	      return row.some(function (v) { return !v; });
233	    });
234	    var cleared = ROWS - kept.length;
235	    while (kept.length < ROWS) {
236	      var empty = [];
237	      for (var c = 0; c < COLS; c++) empty.push(null);
238	      kept.unshift(empty);
239	    }
240	    board = kept;
241	    if (cleared > 0) {
242	      score += LINE_SCORES[cleared] * level;
243	      lines += cleared;
244	      var newLevel = Math.floor(lines / 10) + 1;
245	      if (newLevel !== level) {
246	        level = newLevel;
247	        if (status === "running") startTimer();
248	      }
249	    }
250	  }
251	
252	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
253	  function lockPiece() {
254	    cellsOf(current, current.row, current.col).forEach(function (rc) {
255	      board[rc[0]][rc[1]] = current.type;
256	    });
257	    current = null;
258	    clearLines();
259	    spawn();
260	  }
261	
262	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
263	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
264	  function gravityStep() {
265	    if (status !== "running" || !current) return;
266	    if (fits(current, current.row + 1, current.col)) {
267	      current.row += 1;
268	      current.lockTicks = 0;
269	    } else {
270	      current.lockTicks += 1;
271	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
272	    }
273	  }
274	
275	  // [REQ-002] Restart the lock delay, at most 3 times per piece.
276	  // [REQ-005] Sideways moves and soft drops on a resting piece share this budget.
277	  function resetLock() {
278	    if (current.lockResets < MAX_LOCK_RESETS) {
279	      current.lockResets += 1;
280	      current.lockTicks = 0;
281	    }
282	  }
283	
284	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay.
285	  function shift(dx) {
286	    if (!fits(current, current.row, current.col + dx)) return;
287	    var resting = !fits(current, current.row + 1, current.col);
288	    current.col += dx;
289	    if (resting) resetLock();
290	  }
291	
292	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
293	  function rotateCW() {
294	    var n = BOX[current.type];
295	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
296	    for (var i = 0; i < KICKS.length; i++) {
297	      if (fits(rotated, current.row, current.col + KICKS[i])) {
298	        current.cells = rotated.cells;
299	        current.col += KICKS[i];
300	        return;
301	      }
302	    }
303	  }
304	
305	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW.
306	  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
307	  // [REQ-005] Soft drop on a resting piece scores nothing but restarts the lock delay like a sideways move.
308	  function doInput(action) {
309	    if (status !== "running" || !current) return;
310	    if (action === "left") {
311	      shift(-1);
312	    } else if (action === "right") {
313	      shift(1);
314	    } else if (action === "rotateCW") {
315	      rotateCW();
316	    } else if (action === "softDrop") {
317	      if (fits(current, current.row + 1, current.col)) {
318	        current.row += 1;
319	        score += SOFT_DROP_POINTS;
320	      } else {
321	        resetLock();
322	      }
323	    } else if (action === "hardDrop") {
324	      while (fits(current, current.row + 1, current.col)) {
325	        current.row += 1;
326	        score += HARD_DROP_POINTS;
327	      }
328	      lockPiece();
329	    }
330	  }
331	
332	  function gravityInterval() {
333	    return Math.max(100, 1000 - (level - 1) * 90);
334	  }
335	
336	  function stopTimer() {
337	    if (timer !== null) { clearInterval(timer); timer = null; }
338	  }
339	
340	  function startTimer() {
341	    stopTimer();
342	    timer = setInterval(function () {
343	      gravityStep();
344	      render();
345	    }, gravityInterval());
346	  }
347	
348	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
349	  function render() {
350	    var drawn = board.map(function (row) { return row.slice(); });
351	    if (current) {
352	      cellsOf(current, current.row, current.col).forEach(function (rc) {
353	        drawn[rc[0]][rc[1]] = current.type;
354	      });
355	    }
356	    for (var r = 0; r < ROWS; r++) {
357	      for (var c = 0; c < COLS; c++) {
358	        var v = drawn[r][c] || "";
359	        var el = cellEls[r][c];
360	        if (el.getAttribute("data-piece") !== v) {
361	          el.setAttribute("data-piece", v);
362	          el.setAttribute("data-filled", v ? "true" : "false");
363	        }
364	      }
365	    }
366	    // [REQ-004] Upcoming pieces in their board colour. [REQ-006] Only the next one is shown.
367	    previewItems.forEach(function (item, i) {
368	      var type = upcoming[i] || "";
369	      item.el.setAttribute("data-piece", type);
370	      item.el.hidden = !type;
371	      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
372	      if (type) {
373	        SHAPES[type].forEach(function (o) {
374	          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
375	        });
376	      }
377	    });
378	    scoreEl.textContent = String(score);
379	    levelEl.textContent = String(level);
380	    linesEl.textContent = String(lines);
381	    statusEl.hidden = status !== "gameover";
382	  }
383	
384	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
385	  function newGame(queue) {
386	    board = emptyBoard();
387	    score = 0;
388	    level = 1;
389	    lines = 0;
390	    status = "running";
391	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
392	    current = null;
393	    spawn();
394	    if (status === "running") startTimer();
395	    render();
396	  }
397	
398	  window.__tetris = {
399	    newGame: function (queue) { newGame(queue); },
400	
401	    setQueue: function (queue) {
402	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
403	      fillUpcoming();
404	      render();
405	    },
406	
407	    setBoard: function (rows) {
408	      var b = emptyBoard();
409	      for (var r = 0; r < ROWS; r++) {
410	        var line = (rows && rows[r]) || "";
411	        for (var c = 0; c < COLS; c++) {
412	          var ch = line.charAt(c);
413	          b[r][c] = isType(ch) ? ch : null;
414	        }
415	      }
416	      board = b;
417	      render();
418	    },
419	
420	    tick: function (n) {
421	      if (n === undefined) n = 1;
422	      for (var i = 0; i < n; i++) gravityStep();
423	      if (status === "running") startTimer();
424	      render();
425	    },
426	
427	    input: function (action) {
428	      doInput(action);
429	      render();
430	    },
431	
432	    getBoard: function () {
433	      return board.map(function (row) {
434	        return row.map(function (v) { return v || "."; }).join("");
435	      });
436	    },
437	
438	    getState: function () {
439	      return {
440	        current: current
441	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
442	          : null,
443	        next: upcoming.slice(),
444	        score: score,
445	        level: level,
446	        lines: lines,
447	        status: status
448	      };
449	    }
450	  };
451	
452	  var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop" };
453	
454	  document.addEventListener("keydown", function (e) {
455	    var action = KEYS[e.key];
456	    if (!action) return;
457	    e.preventDefault();
458	    window.__tetris.input(action);
459	  });
460	
461	  document.getElementById("restart").addEventListener("click", function (e) {
462	    e.currentTarget.blur();
463	    newGame();
464	  });
465	
466	  buildDom();
467	  newGame();
468	})();
469	</script>
470	</body>
471	</html>
